package ai.eva.android.probe;
import android.app.*;import android.os.*;import org.json.*;
public class QuotaCheck extends Instrumentation{
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();int code=0;try{JSONObject window=new JSONObject().put("windowDurationMins",300).put("usedPercent",25).put("resetsAt",1800000000);JSONObject snapshot=new JSONObject().put("primary",window).put("credits",new JSONObject().put("hasCredits",true).put("balance","12.5"));JSONObject quota=new JSONObject().put("rateLimitsByLimitId",new JSONObject().put("codex",snapshot)).put("ordinaryUsageAllowed",false);String text=AccountQuota.describe(quota);if(!text.contains("剩余 75%")||!text.contains("5 小时")||!text.contains("12.5")||!text.contains("当前可用：否"))throw new Exception("quota presentation mismatch");String unknown=AccountQuota.window(new JSONObject(),"额度");if(unknown.contains("剩余 100%")||!unknown.contains("暂不可读取"))throw new Exception("unknown usage presented as available");window.put("usedPercent",105);if(!AccountQuota.window(window,"额度").contains("剩余 0%"))throw new Exception("negative remainder");if(!AccountQuota.describe(null).contains("暂不可读取"))throw new Exception("missing error state");out.putString("result","PASS: quota windows, remaining/used percentages, reset time, extra credits, explicit unavailable usage, unknown values; synthetic data only");}catch(Exception e){code=1;out.putString("error",e.getMessage());}finish(code,out);}
}
